-- Generated by model/lib/sql/generate.mjs. Loads Price Increase IN from cells/Price Increase IN.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/Price Increase IN.csv
INSERT INTO "Price Increase IN" SELECT coalesce(k0."Brand", fpabench_error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k1."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Brand" k0 ON k0.name = c."Brand" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY 1, 2, 3
ON CONFLICT ("Brand", "Versions", "Years") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "Price Increase IN";
